class Stack<T> {
  private items: T[] = [];
  push(x: T) { this.items.push(x); }
  pop(): T | undefined { return this.items.pop(); }
  static from(initial: T[]): Stack<T> { // Error: static references T
    const s = new Stack<T>();
    initial.forEach(x => s.push(x));
    return s;
  }
}

